from lib import *
S = SS('x44')
steps = [
    step("两个 Filter(F1 order 1、F2 order 2)、一个 OncePerRequestFilter(order 3)、两个拦截器(A order 1,路径 /api/**、/open/**、/nope**;B order 2,路径 /api/**)。GET /api/hi 的实际顺序:F1 进入 → F2 进入 → Once 进入 → A.preHandle → B.preHandle → Controller → B.postHandle → A.postHandle → B.afterCompletion → A.afterCompletion → F2 返回 → F1 返回。拦截器的 preHandle 按 order 升序,postHandle 和 afterCompletion 倒过来;整个拦截器链被 Filter 包在里面。GET /open/hi 只匹配 A,B 没有被调用。", t=tl(S(1)), mark=lidx(S(1), 'B.preHandle', 'B.postHandle'), done=lidx(S(1), 'F1 进入 /api/hi', 'A.preHandle [REQUEST] handler=hi', 'Controller /api/hi', 'F1 返回', 'GET /open/hi'), b=bars([['/api/hi 经过的 Filter 个数', 3, '3'], ['/api/hi 经过的拦截器个数', 2, '2(A、B)'], ['/open/hi 经过的拦截器个数', 1, '1(只有 A)']], 3, done=[0, 1], mark=[2]), kv=KV([['进入顺序', 'Filter → 拦截器 preHandle → Controller'], ['返回顺序', 'postHandle、afterCompletion 倒序,再到 Filter'], ['拦截器路径', 'addPathPatterns 决定 B 在 /open/hi 上不执行'], ['dispatcher 类型', '都是 REQUEST']], ['返回顺序'])),
    step("把拦截器 B 的 preHandle 改成返回 false(同时设置状态 403)。请求只走到 B.preHandle,Controller 没有被调用,B 的 postHandle 也没有。afterCompletion 只对 preHandle 已经返回 true 的拦截器调用:A.afterCompletion 执行了,B.afterCompletion 没有执行。两个 Filter 都正常「返回」,客户端拿到 403。", t=tl(S(2)), mark=lidx(S(2), 'B 返回 false'), done=lidx(S(2), 'A.afterCompletion', 'F1 返回', 'GET /api/hi → 403'), b=bars([['Controller 被调用次数', 0, '0'], ['B.afterCompletion 被调用次数', 0, '0'], ['A.afterCompletion 被调用次数', 1, '1']], 1, mark=[0, 1], done=[2]), kv=KV([['preHandle 返回 false', 'Controller 与 postHandle 都跳过'], ['afterCompletion', '只对 preHandle 返回过 true 的拦截器倒序调用'], ['Filter', '不受影响,照常返回'], ['客户端', '403']], ['afterCompletion'])),
    step("没有处理器的请求。GET /nope:拦截器 A 的路径模式 /nope** 匹配,请求落到默认的静态资源处理器 ResourceHttpRequestHandler,A.preHandle 被调用,handler 是 ResourceHttpRequestHandler 而不是 HandlerMethod;因为没有找到资源,最终 404,A.afterCompletion 照常调用。GET /static-missing.css:路径不匹配任何拦截器,一个拦截器都没有调用,但三个 Filter 都执行了。Filter 对所有请求都生效,不管有没有 Controller。", t=tl(S(3)), mark=lidx(S(3), 'handler=ResourceHttpRequestHandler'), done=lidx(S(3), 'GET /nope → 404', 'GET /static-missing.css → 404', 'F1 进入 /static-missing.css'), b=bars([['/nope 的 Filter 调用次数', 3, '3'], ['/nope 的拦截器调用次数', 1, '1(A,handler 是资源处理器)'], ['/static-missing.css 的拦截器调用次数', 0, '0']], 3, done=[0], mark=[1, 2]), kv=KV([['404 请求', 'Filter 照常执行'], ['拦截器', '路径匹配才执行,handler 可能不是 HandlerMethod'], ['A 在 /nope 上', 'handler 是 ResourceHttpRequestHandler'], ['只靠拦截器', '看不到不匹配路径的请求']], ['拦截器'])),
    step("读请求体。对照:没有 Filter 读 body 时,POST /api/body 的 Controller 用 @RequestBody 读到 payload,返回 200 got:payload。", t=tl(S(4)), mark=lidx(S(4), 'Controller 读到 body'), done=lidx(S(4), 'POST /api/body → 200'), b=bars([['Controller 读到的 body 长度', 7, '7(payload)'], ['状态码 / 100', 2, '200']], 7, done=[0, 1]), kv=KV([['无 Filter 读 body', 'Controller 正常读到'], ['结果', '200 got:payload']], ['结果'])),
    step("在 order 4 加一个 Filter,先用 getInputStream().readAllBytes() 把请求体读完再放行(它自己读到了 payload)。拦截器 A、B 的 preHandle 照常执行,但到了 Controller 的参数解析:请求体已经被读光,@RequestBody 读不到内容,结果 400,Controller 方法没有被调用;B.afterCompletion、A.afterCompletion 依然执行。Servlet 的输入流只能读一次;想在 Filter 里看 body,要用 ContentCachingRequestWrapper 之类的包装类。", t=tl(S(5)), mark=lidx(S(5), 'POST /api/body → 400', 'BodyReader 在 Filter 里'), done=lidx(S(5), 'A.preHandle', 'B.afterCompletion'), b=bars([['Filter 读到的字节数', 7, '7(payload)'], ['Controller 被调用次数', 0, '0'], ['响应状态码 / 100', 4, '400']], 7, mark=[1, 2], done=[0]), kv=KV([['Filter 读完 body', '输入流只能读一次'], ['@RequestBody', '读不到,400,Controller 没执行'], ['拦截器', 'preHandle / afterCompletion 照常调用'], ['正确做法', '用缓存请求体的包装类']], ['Filter 读完 body'])),
]
A = mkartx('x44', 44, 'Spring,MVC,拦截器,Filter,HandlerInterceptor,真实验证,动画演示',
    '实测 Spring MVC 的拦截器与 Servlet Filter:Filter 包住整个拦截器链,preHandle 升序、postHandle 与 afterCompletion 倒序;preHandle 返回 false 后 Controller 与 postHandle 跳过,afterCompletion 只对返回过 true 的拦截器调用;404 请求 Filter 照常执行而拦截器只看路径匹配;Filter 读完请求体后 @RequestBody 得到 400。',
    '拦截器和 Filter 到底谁先谁后?preHandle 返回 false 之后会发生什么?404 的请求能不能被拦住?在 Filter 里读了请求体为什么 Controller 就读不到了?这篇在 Spring Boot 4.0.8 的 Spring MVC 7.0.9 上逐个打印执行顺序。',
    [('Filter ⊃ 拦截器', 'Filter 先进入、最后返回;拦截器链被包在里面'), ('B 没有 afterCompletion', 'B 的 preHandle 返回 false 后,B.afterCompletion 不会执行,A 的会'), ('400', 'Filter 读完请求体之后,@RequestBody 的结果')],
    [('执行顺序', '<p>Filter → 拦截器 preHandle(升序)→ Controller → postHandle、afterCompletion(倒序)→ Filter 返回。</p>'),
     ('中止', '<p>preHandle 返回 false 后只对已返回 true 的拦截器调用 afterCompletion。</p>'),
     ('能看到什么', '<p>Filter 对所有请求生效,拦截器只对匹配路径、有处理器的请求生效,并能拿到 HandlerMethod。</p>'),
     ('读 body', '<p>Servlet 输入流只能读一次,Filter 里读 body 要用缓存包装类。</p>'),
     ('读 body 的后果', '<p>Filter 读完 body,@RequestBody 读不到,返回 400。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8 的 SpringApplication(spring-boot-starter-webmvc,内嵌 Tomcat 11);Filter 用 FilterRegistrationBean 设置 order,拦截器用 WebMvcConfigurer.addInterceptors;每一行事件由应用自己打印,不是框架日志',
     '没有验证:异步请求(DeferredResult、Callable)上拦截器与 Filter 的二次调度与 AsyncHandlerInterceptor;ERROR 派发与 FORWARD 派发下 Filter 的注册范围;ContentCachingRequestWrapper 的实际用法与内存开销;Spring Security 过滤器链与自定义 Filter 的相对位置(见 Security 章节);WebFlux 的 WebFilter'],
    '拦截器与 Filter')
